from textlesson import build
S=dict(cls=6,subj="social-science",subj_file="social-science")
build(dict(S,ch="family-and-community",topic="family-and-community-life",name_en="Family and community life",name_ta="குடும்பமும் சமூக வாழ்வும்",
 objectives=["Describe kinds of families and what a family does","Explain what a community is and why we cooperate"],
 story=("The flooded street","After heavy rain, water filled Seema's street. Her family had no gas for cooking.\nThe neighbours shared food and gave her baby brother milk. Young people helped carry old people to dry places.\n\"We are a family, and the street is our community,\" Seema's grandfather said."),
 explain=["A family is a group of people who live together and care for each other. A nuclear family has parents and children. A joint family has several generations living together, such as grandparents, parents, uncles, aunts and cousins.","A family gives us love, food, shelter, safety and our first lessons about right and wrong. Each member has a role, and we help each other.","A community is a group of people living in the same area or sharing the same interests, such as neighbours in a street, a village or a school. Communities work together on festivals, cleanliness and in times of trouble.","We belong to many communities: family, school, neighbourhood, village or town, and country.","Good communities depend on cooperation, respect, sharing and responsibility."],
 terms=["family","nuclear family","joint family","community","cooperation"],
 narr=[("A family is a group that lives together and cares for each other.","family"),("A nuclear family has parents and children. A joint family has many relatives together.","nuclear / joint"),("A community is a group living in one area, like a street, a village or a school.","community"),("Good communities share, cooperate, and help each other in trouble.","cooperation")],
 ex=("Name two ways a community helps its members.",[("Neighbours help each other in trouble, such as floods.","Help in need builds trust."),("People share festivals, water and safety.","Sharing makes life easier."),("So communities help through cooperation and sharing.","Together we can do more.")]),
 tb=("A friend says it is not his job to keep the street clean. What will you say?",["The street is shared by the whole community.","When everyone does a little, the street stays clean for all."],["Thinking only others are responsible."]),
 summary=["Families can be nuclear or joint.","A community is a group living together or sharing interests.","Cooperation makes communities strong."],
 q=[("mcq",1,"r1-nuclear","A nuclear family has","parents and children",[("only grandparents","That is not a nuclear family."),("many cousins and uncles","That describes a joint family.")],"A nuclear family is parents and children."),
    ("tf",1,"r1-care","Family members care for each other.",True,"True."),
    ("mcq",2,"r2-joint","In a joint family","several generations live together",[("one person lives alone","That is not a family."),("only friends live","Friends are not family.")],"Grandparents, parents and cousins live together."),
    ("tf",2,"r2-comm","A school can be a community.",True,"True."),
    ("mcq",3,"r3-help","What do neighbours do in a flood?","help each other",[("ignore each other","Good communities cooperate."),("close their doors","Good communities cooperate.")],"Neighbours help during trouble."),
    ("short",3,"r3-community","Name one community you belong to.",["family","school","street","village","neighbourhood","town","class"],"We belong to many communities."),
    ("mcq",4,"r4-coop","Which keeps a community strong?","cooperation and respect",[("fights","Fights weaken a community."),("selfishness","Selfishness weakens a community.")],"Respect and cooperation make a community strong."),
    ("tf",4,"r4-street","Keeping the street clean is the duty of everyone in the community.",True,"True.")]))
build(dict(S,ch="grassroots-democracy-part-1-governance",topic="governance-and-democracy",name_en="Governance and democracy",name_ta="ஆட்சியும் மக்களாட்சியும்",
 objectives=["Say why governance is needed","Explain voting and elected representatives"],
 story=("The class monitor election","Class 6 had to choose a monitor. Each candidate told the class what they would do. Everyone voted with a slip of paper and the one with the most votes became monitor.\n\"This is how our country chooses leaders too,\" said the teacher."),
 explain=["Governance means managing a community, village, city or country: making rules, providing services such as water, roads, schools and hospitals, and keeping people safe.","In a democracy, the people have the power to choose who will govern them. India is the largest democracy in the world.","Citizens aged 18 and above can vote. They elect representatives in elections by secret ballot. The representatives make decisions for everyone and must answer to the people.","Governance in India works at three levels: local (village and town), state and national (the Union).","Local governance is closest to people. It deals with daily needs such as clean water, streets, lights and rubbish."],
 terms=["governance","democracy","election","representative","vote"],
 narr=[("Governance means running a place: making rules and giving services like water, roads and schools.","governance"),("In a democracy, people choose their government through elections.","democracy: people choose"),("Every citizen aged eighteen or more can vote. The vote is secret.","vote at 18"),("Governance has three levels: local, state and national. Local governance is closest to us.","local, state, national")],
 ex=("Why is a secret ballot important in an election?",[("In a secret ballot, no one knows whom you voted for.","It hides your choice from others."),("So nobody can force or pressure you.","You can choose freely."),("That makes elections fair.","Fair elections protect democracy.")]),
 tb=("A friend says his vote does not matter because there are millions of voters. How will you reply?",["Every vote counts, and many votes together decide the result.","Voting is how citizens choose who governs them."],["Thinking one vote has no value."]),
 summary=["Governance means managing a place and its services.","In a democracy people choose representatives by voting.","There are local, state and national levels."],
 q=[("mcq",1,"r1-democracy","In a democracy, who chooses the government?","the people",[("one king","That is not a democracy."),("a foreign country","The people choose in a democracy.")],"People elect the government."),
    ("tf",1,"r1-vote","Citizens aged 18 and above can vote.",True,"True."),
    ("mcq",2,"r2-gov","Governance means","managing a place and giving services",[("playing games","Governance is about running a place."),("making films","Governance is about running a place.")],"Governance runs a village, city or country."),
    ("tf",2,"r2-secret","A vote is kept secret.",True,"True. This keeps the election fair."),
    ("mcq",3,"r3-level","Which is closest to people?","local governance",[("only the national government","Local is closest to people."),("no government","Government exists at several levels.")],"Local governance deals with daily needs."),
    ("short",3,"r3-rep","What do we call a person chosen by voters?",["representative","leader","elected representative"],"They are elected representatives."),
    ("mcq",4,"r4-largest","India is the world's largest","democracy",[("desert","India is a democracy."),("island","India is a democracy.")],"India has the largest number of voters."),
    ("tf",4,"r4-count","One vote does not count at all.",False,"False. Every vote counts.")]))
build(dict(S,ch="grassroots-democracy-part-2-local-government-in-rural-areas",topic="the-village-panchayat",name_en="The village panchayat",name_ta="கிராம பஞ்சாயத்து",
 objectives=["Name the three levels of panchayati raj","Say what a Gram Sabha and a Gram Panchayat do"],
 story=("The village meeting","Every few months the people of Kamala's village met under a big tree. They talked about the broken hand pump and a new school room.\nThe sarpanch listened and wrote down every request.\n\"This meeting is the Gram Sabha,\" said her mother. \"Every adult voter of the village can speak.\""),
 explain=["Local government in villages is called panchayati raj. It works at three levels: the Gram Panchayat (village), the Panchayat Samiti (block) and the Zila Parishad (district).","All the adult voters of a village form the Gram Sabha. It meets and discusses village matters and questions the Panchayat's work.","The Gram Panchayat is the elected body of the village. Its head is the Sarpanch (called by other names in some states). Members are elected by voters for five years.","A Panchayat looks after drinking water, village roads, street lights, drains, schools, health centres and village markets. It collects small taxes and gets money from the government.","Panchayati raj gives power to people at the grassroots, so that villagers can decide about their own needs."],
 terms=["panchayat","Gram Sabha","Sarpanch","Zila Parishad"],
 narr=[("Local government in villages is called panchayati raj. It has three levels.","panchayati raj: 3 levels"),("The Gram Sabha is all the adult voters of the village.","Gram Sabha: all adult voters"),("The Gram Panchayat is the elected body. Its head is the Sarpanch, elected for five years.","Gram Panchayat, Sarpanch"),("It looks after water, roads, lights and schools in the village.","village needs")],
 ex=("Name the three levels of panchayati raj in order from village to district.",[("The village level is the Gram Panchayat.","It is closest to people."),("The block level is the Panchayat Samiti.","It is in the middle."),("The district level is the Zila Parishad.","It is the highest of the three.")]),
 tb=("A friend asks who decides about the village water pump. What will you say?",["The Gram Sabha discusses it and the Gram Panchayat acts on it.","The Panchayat is elected by the people of the village."],["Thinking only officers far away decide."]),
 summary=["Panchayati raj has three levels.","Gram Sabha is all adult voters of a village.","The Gram Panchayat is elected for five years and looks after village needs."],
 q=[("mcq",1,"r1-head","Who heads the Gram Panchayat?","the Sarpanch",[("the Mayor","A Mayor heads a city corporation."),("the Prime Minister","The Prime Minister heads the national government.")],"The Sarpanch heads the Gram Panchayat."),
    ("tf",1,"r1-gs","All adult voters of a village form the Gram Sabha.",True,"True."),
    ("mcq",2,"r2-levels","How many levels does panchayati raj have?","three",[("one","There are three."),("five","There are three.")],"Gram Panchayat, Panchayat Samiti and Zila Parishad."),
    ("tf",2,"r2-term","Panchayat members are elected for five years.",True,"True."),
    ("mcq",3,"r3-district","The panchayat body at district level is the","Zila Parishad",[("Gram Sabha","That is the village body of voters."),("Municipal Corporation","That is for big cities.")],"Zila Parishad works at district level."),
    ("short",3,"r3-job","Name one job of a Gram Panchayat.",["water","roads","street lights","drains","schools","sanitation","health"],"It looks after water, roads, lights and schools."),
    ("mcq",4,"r4-why","Why is panchayati raj useful?","villagers decide about their own needs",[("it closes villages","It does the opposite."),("it removes elections","It depends on elections.")],"It gives power to the people at the grassroots."),
    ("tf",4,"r4-meet","The Gram Sabha meets to discuss village matters.",True,"True.")]))
build(dict(S,ch="grassroots-democracy-part-3-local-government-in-urban-areas",topic="the-city-municipality",name_en="The city municipality",name_ta="நகராட்சி",
 objectives=["Name the kinds of urban local bodies","Say what a municipality looks after"],
 story=("The rubbish truck","Every morning a truck came to collect rubbish in Rahul's city. One day it did not come, and the smell spread.\nHis father called the ward councillor, and by evening the truck was back.\n\"The city's local government looks after these things,\" he said."),
 explain=["Local government in towns and cities is called urban local government. In big cities it is a Municipal Corporation. In smaller towns it is a Municipality (Nagar Palika), and in small urban areas a Nagar Panchayat.","A city is divided into wards. People of each ward elect a councillor. The councillors together form the council. The Mayor heads a Municipal Corporation.","Municipalities look after water supply, roads, street lights, drains, rubbish collection, public toilets, parks and markets. They also give birth and death certificates.","They get money from taxes such as house tax and water charges, and from the government.","Elections are held every five years. Citizens can tell their councillor about problems in their ward."],
 terms=["municipality","Municipal Corporation","ward","councillor","Mayor"],
 narr=[("In towns and cities, local government is the municipality. Big cities have a Municipal Corporation.","urban local government"),("A city has wards. Each ward elects a councillor.","ward -> councillor"),("A Mayor heads a Municipal Corporation.","Mayor"),("The municipality looks after water, roads, lights and rubbish.","city services")],
 ex=("Who should you tell if the street light in your ward is not working?",[("Street lights are looked after by the municipality.","It is a city service."),("Each ward has an elected councillor.","The councillor listens to ward problems."),("So tell the ward councillor or the municipal office.","They can arrange the repair.")]),
 tb=("A friend says the city's rubbish is not the government's job. What will you say?",["The municipality is the local government and rubbish collection is one of its main jobs.","We should also keep the city clean by not littering."],["Thinking only people should keep the city clean."]),
 summary=["Urban local bodies: Municipal Corporation, Municipality, Nagar Panchayat.","Each ward elects a councillor; a Mayor heads a corporation.","They look after water, roads, lights and rubbish."],
 q=[("mcq",1,"r1-corp","Which body governs a big city?","Municipal Corporation",[("Gram Sabha","That is a village body."),("Zila Parishad","That is a district body in the panchayat system.")],"Big cities have a Municipal Corporation."),
    ("tf",1,"r1-ward","A city is divided into wards.",True,"True."),
    ("mcq",2,"r2-mayor","Who heads a Municipal Corporation?","the Mayor",[("the Sarpanch","The Sarpanch heads a Gram Panchayat."),("the Chief Minister","The Chief Minister heads the state government.")],"The Mayor heads it."),
    ("tf",2,"r2-councillor","Each ward elects a councillor.",True,"True."),
    ("mcq",3,"r3-job","Which job does a municipality do?","collect rubbish",[("make films","That is not a municipal job."),("run railways","The railways run nationally.")],"Rubbish, water, roads and lights are municipal services."),
    ("short",3,"r3-service","Name one service of a municipality.",["water","roads","street lights","drains","rubbish","garbage","parks","toilets"],"Municipalities give many city services."),
    ("mcq",4,"r4-term","Municipal elections are held every","five years",[("year","The term is five years."),("fifty years","The term is five years.")],"Councillors are elected for five years."),
    ("tf",4,"r4-tell","Citizens can tell their councillor about problems in their ward.",True,"True.")]))
build(dict(S,ch="the-value-of-work",topic="why-work-matters",name_en="Why work matters",name_ta="வேலையின் மதிப்பு",
 objectives=["Explain why all work deserves respect","Tell paid work from unpaid work"],
 story=("A day without helpers","One morning there was no milk, no vegetable seller, the sweeper did not come and the bus did not run.\nNisha realised how much she depended on people she hardly noticed.\n\"Every kind of work matters,\" her mother said."),
 explain=["Work is what people do to earn a living or to take care of others. Farmers grow food, tailors stitch clothes, teachers teach, drivers carry people and doctors heal.","Some work is paid, such as a job or a business. Some work is unpaid but very important, such as cooking and caring for the family at home.","We depend on each other's work. No one can do everything for themselves. This is called interdependence.","All honest work deserves respect. The dignity of labour means that no honest work is small or low.","Work gives us money, skills, pride and a sense of purpose. We should also learn to share household work and respect those who work with their hands."],
 terms=["work","livelihood","interdependence","dignity of labour"],
 narr=[("Work is what people do to earn a living or look after others.","work"),("Some work is paid and some is unpaid, like caring for family at home. Both are important.","paid and unpaid work"),("We depend on each other's work. This is interdependence.","interdependence"),("All honest work deserves respect. This is the dignity of labour.","respect all work")],
 ex=("Is cooking at home work even if no one pays for it?",[("Cooking is useful and takes time and effort.","These are signs of work."),("It is unpaid, but it keeps the family healthy.","Unpaid work has value."),("So yes, it is real and important work.","It deserves respect.")]),
 tb=("A friend laughs at a child whose father sweeps the road. What will you say?",["All honest work deserves respect.","Sweepers keep our city clean and healthy, so we depend on them."],["Thinking some jobs are low."]),
 summary=["Work earns a living or cares for others.","Paid and unpaid work both matter.","All honest work deserves respect."],
 q=[("mcq",1,"r1-work","Which of these is work?","a farmer growing food",[("sleeping all day","That is not work."),("watching a film","That is not work.")],"Growing food is work."),
    ("tf",1,"r1-unpaid","Cooking and caring at home are unpaid but important work.",True,"True."),
    ("mcq",2,"r2-depend","We depend on each other's work. This is called","interdependence",[("independence","That means needing no one."),("competition","That is about contest.")],"We need each other."),
    ("tf",2,"r2-small","Some honest jobs are not worth respect.",False,"False. All honest work deserves respect."),
    ("mcq",3,"r3-dignity","Dignity of labour means","every honest work is respected",[("only office jobs are good","That is not the idea."),("work is for others only","Everyone can work.")],"No honest work is small."),
    ("short",3,"r3-example","Name a job that helps your community.",["doctor","teacher","farmer","driver","sweeper","tailor","nurse","police","postman"],"Many jobs help the community."),
    ("mcq",4,"r4-sweeper","Why should we respect a sweeper?","he or she keeps our city clean and healthy",[("sweeping is easy","Respect does not depend on ease."),("they are rich","Wealth is not the reason.")],"We depend on such work."),
    ("tf",4,"r4-share","Household work should be shared in a family.",True,"True.")]))
build(dict(S,ch="economic-activities-around-us",topic="kinds-of-economic-activity",name_en="Kinds of economic activity",name_ta="பொருளாதாரச் செயல்பாடுகளின் வகைகள்",
 objectives=["Name primary, secondary and tertiary activities","Say how goods and services reach us"],
 story=("From field to plate","Ria ate a plate of idli. Farmers had grown the rice and urad. A mill ground them into flour and a shop sold it. A cook made the idli and a delivery boy brought it.\n\"So many people worked to make my breakfast,\" she said."),
 explain=["Economic activities are things people do to earn money or produce goods and services we need.","Primary activities take things from nature: farming, fishing, mining and cutting wood.","Secondary activities turn raw things into other things: factories make cloth, a mill turns wheat into flour, a carpenter makes a table.","Tertiary activities are services: teaching, healing, transport, banking, shopping and communication.","Long ago people exchanged goods directly (barter). Now we use money. Markets and shops bring producers and buyers together. We buy what we need and also what we want."],
 terms=["primary","secondary","tertiary","barter","goods","services"],
 narr=[("Economic activities are things we do to earn and to provide goods and services.","economic activities"),("Primary activities take from nature, like farming, fishing and mining.","primary: from nature"),("Secondary activities make new things, like a mill making flour.","secondary: making things"),("Tertiary activities are services, like teaching, healing and transport.","tertiary: services")],
 ex=("A farmer grows wheat, a mill makes flour and a shop sells it. Which activity is each?",[("Growing wheat takes from nature: primary.","Farming is primary."),("The mill makes flour from wheat: secondary.","Manufacturing is secondary."),("The shop sells to people: tertiary.","Trade is a service.")]),
 tb=("A friend says a teacher does not do any economic activity because she makes nothing. What will you say?",["A teacher provides a service, which is a tertiary activity.","Services are an important part of the economy."],["Thinking only things you can touch count."]),
 summary=["Primary: from nature. Secondary: making things. Tertiary: services.","Barter was exchange without money.","Markets bring sellers and buyers together."],
 q=[("mcq",1,"r1-farm","Farming is","a primary activity",[("a secondary activity","Secondary makes new things."),("a tertiary activity","Tertiary is a service.")],"Farming takes from nature."),
    ("tf",1,"r1-mill","A flour mill turns wheat into flour.",True,"True. This is a secondary activity."),
    ("mcq",2,"r2-teach","Teaching is","a tertiary activity",[("a primary activity","Primary takes from nature."),("a secondary activity","Secondary makes goods.")],"Teaching is a service."),
    ("tf",2,"r2-barter","Barter means exchanging goods without money.",True,"True."),
    ("mcq",3,"r3-fish","Fishing and mining are","primary activities",[("secondary activities","They take from nature."),("tertiary activities","They are not services.")],"They take things from nature."),
    ("short",3,"r3-service","Name one service.",["teaching","transport","banking","healing","medical","shopping","delivery","driving"],"Teaching, transport and healing are services."),
    ("mcq",4,"r4-factory","A factory making cloth is","a secondary activity",[("a primary activity","It makes things from raw material."),("barter","Barter is exchange without money.")],"Making things is secondary."),
    ("tf",4,"r4-market","Markets bring sellers and buyers together.",True,"True.")]))
